248: int run(int argc, char **argv, int is_gui) {
249: 
250:     char python[256];   /* python executable's filename*/
251:     char *pyopt;        /* Python option */
252:     char script[256];   /* the script's filename */
253: 
254:     int scriptf;        /* file descriptor for script file */
255: 
256:     char **newargs, **newargsp, **parsedargs; /* argument array for exec */
257:     char *ptr, *end;    /* working pointers for string manipulation */
258:     char *cmdline;
259:     int i, parsedargc;              /* loop counter */
260: 
261:     /* compute script name from our .exe name*/
262:     GetModuleFileNameA(NULL, script, sizeof(script));
263:     /* resolve final path in case script name is symlink */
264:     HANDLE hFile = CreateFile(script,
265:                    GENERIC_READ,
266:                    FILE_SHARE_READ,
267:                    NULL,
268:                    OPEN_EXISTING,
269:                    FILE_ATTRIBUTE_NORMAL,
270:                    NULL);
271:     GetFinalPathNameByHandle(hFile, script, 256, VOLUME_NAME_DOS);
272:     
273:     end = script + strlen(script);
274:     while( end>script && *end != '.')
275:         *end-- = '\0';
276:     *end-- = '\0';
277:     strcat(script, (GUI ? "-script.pyw" : "-script.py"));
278: 
279:     /* figure out the target python executable */
280: 
281:     scriptf = open(script, O_RDONLY);
282:     if (scriptf == -1) {
283:         return fail("Cannot open %s\n", script);
284:     }
285:     end = python + read(scriptf, python, sizeof(python));
286:     close(scriptf);
287: 
288:     ptr = python-1;
289:     while(++ptr < end && *ptr && *ptr!='\n' && *ptr!='\r') {;}
290: 
291:     *ptr-- = '\0';
292: 
293:     if (strncmp(python, "#!", 2)) {
294:         /* default to python.exe if no #! header */
295:         strcpy(python, "#!python.exe");
296:     }
297: 
298:     parsedargs = parse_argv(python+2, &parsedargc);
299: 
300:     /* Using spawnv() can fail strangely if you e.g. find the Cygwin
301:        Python, so we'll make sure Windows can find and load it */
302: 
303:     ptr = find_exe(parsedargs[0], script);
304:     if (!ptr) {
305:         return fail("Cannot find Python executable %s\n", parsedargs[0]);
306:     }
307: 
308:     /* printf("Python executable: %s\n", ptr); */
309: 
310:     /* Argument array needs to be
311:        parsedargc + argc, plus 1 for null sentinel */
312: 
313:     newargs = (char **)calloc(parsedargc + argc + 1, sizeof(char *));
314:     newargsp = newargs;
315: 
316:     *newargsp++ = quoted(ptr);
317:     for (i = 1; i<parsedargc; i++) *newargsp++ = quoted(parsedargs[i]);
318: 
319:     *newargsp++ = quoted(script);
320:     for (i = 1; i < argc; i++)     *newargsp++ = quoted(argv[i]);
321: 
322:     *newargsp++ = NULL;
323: 
324:     /* printf("args 0: %s\nargs 1: %s\n", newargs[0], newargs[1]); */
325: 
326:     if (is_gui) {
327:         /* Use exec, we don't need to wait for the GUI to finish */
328:         execv(ptr, (const char * const *)(newargs));
329:         return fail("Could not exec %s", ptr);   /* shouldn't get here! */
330:     }
331: 
332:     /*
333:      * distribute-issue207: using CreateProcessA instead of spawnv
334:      */
335:     cmdline = join_executable_and_args(ptr, newargs, parsedargc + argc);
336:     return create_and_wait_for_subprocess(cmdline);
337: }
338: 
339: int WINAPI WinMain(HINSTANCE hI, HINSTANCE hP, LPSTR lpCmd, int nShow) {
340:     return run(__argc, __argv, GUI);
341: }
342: 
343: int main(int argc, char** argv) {
344:     return run(argc, argv, GUI);
345: }

